#!/usr/bin/env python3
"""Package a verified friend-release handoff; reject missing release evidence."""
from pathlib import Path
import argparse,base64,hashlib,html,json
p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('--out',type=Path,required=True);a=p.parse_args();m=json.loads(a.manifest.read_text());e=lambda x:html.escape(str(x),quote=True)
for k in ['version','downloadURL','releaseURL','zipSHA256','steps','requirements','limits','verifiedChecks','sourceCommit']:
 if not m.get(k):raise SystemExit('Missing '+k)
if m.get('releaseVerified') is not True:raise SystemExit('Release is not verified; refuse ready-to-download artifact')
if len(m['zipSHA256'])!=64:raise SystemExit('Expected full release ZIP SHA-256')
for k in ['downloadURL','releaseURL']:
 if not m[k].startswith('https://github.com/amiller/apple-attest-p2p/releases/'):raise SystemExit('Unexpected release URL')
items=lambda xs:''.join('<li>'+e(x)+'</li>' for x in xs)
shots=[]
for shot in m.get('screenshots',[]):
 path=(a.manifest.parent/shot['path']).resolve();data=path.read_bytes()
 if path.suffix.lower()!='.png' or hashlib.sha256(data).hexdigest()!=shot['sha256']:raise SystemExit('Screenshot differs from reviewed bytes')
 shots.append('<figure><img src="data:image/png;base64,'+base64.b64encode(data).decode()+'" alt="'+e(shot['caption'])+'"><figcaption>'+e(shot['caption'])+'</figcaption></figure>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AttestNode — try the Mac release</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f5f0;color:#111;font:16px/1.55 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}main{max-width:1050px;margin:auto;padding:42px 28px}.eyebrow{border-left:5px solid #df321d;padding-left:12px;font:11px ui-monospace,monospace;letter-spacing:1px}h1{font-size:clamp(48px,7vw,82px);line-height:.97;letter-spacing:-3px;margin:28px 0}h2{font-size:30px;line-height:1.1;letter-spacing:-1px}p{max-width:780px;color:#53555d}.button{display:inline-block;background:#111;color:#fff;text-decoration:none;padding:15px 23px;border-radius:5px;font-weight:650}.button:hover{background:#245bea}a{color:#b52b19;text-underline-offset:4px}a:focus-visible{outline:3px solid #245bea;outline-offset:4px}.requirements{margin:24px 0;padding:18px 22px;background:#e9edf8}.requirements ul{margin:0;padding-left:20px}section{margin-top:36px;border-top:1px solid #c7c8c2;padding-top:22px}ol{padding-left:24px}li{margin:13px 0}figure{margin:28px 0}img{display:block;max-width:100%;height:auto;border:1px solid #cccdc6;border-radius:8px}figcaption{font-size:12px;color:#5c5e67;margin-top:10px}.links{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:25px 0}.meta{font:11px/1.7 ui-monospace,monospace;color:#5c5e67;overflow-wrap:anywhere}.limits{background:#eeeee8;padding:18px 24px;font-size:14px}.footer{font-size:12px;border-top:1px solid #c7c8c2;margin-top:32px;padding-top:18px}summary{cursor:pointer;font-weight:600}details li{font-size:13px}@media(max-width:600px){main{padding:27px 18px}h1{letter-spacing:-2px}.button{display:block;text-align:center}.links{display:block}.links>a{margin:12px 0;display:block}h2{font-size:27px}}</style></head><body><main><div class="eyebrow">ATTESTNODE / ASSEMBLY / __VERSION__</div><h1>Join the network.</h1><p>Open the Mac app to join the research testnet and claim your participant receipt. No wallet, gas purchase, Xcode or developer account is needed for this first step.</p><div class="links"><a class="button" href="__DOWNLOAD__">Download for Mac ↓</a><a href="__RELEASE__">Release notes and checksums ↗</a></div><div class="requirements"><ul>__REQUIREMENTS__</ul></div><section><h2>From download to connected.</h2><ol>__STEPS__</ol>__SCREENSHOTS__</section><section><h2>If something stops you.</h2><p>__HELP__</p><p>Keep the app’s saved identity and Keychain entries. They hold access to your account; deleting them is not a routine retry step.</p></section><section><h2>The next level is optional.</h2><p>Joining needs no Apple Developer account. Becoming an independent builder requires your own paid Apple Developer team and an independently signed copy. Keep the original app and its Keychain until the account handoff is confirmed.</p><p><a href="https://github.com/amiller/apple-attest-p2p/blob/main/release/builder-guide.md">Read the independent-builder guide ↗</a></p></section><section class="limits"><h2>What this release does—and what remains.</h2><ul>__LIMITS__</ul><p><a href="https://sepolia.basescan.org/token/0xc3da5f4d5013dD6fB4a16EF3ace0C0F9e1F8C1Ed">View the main Fold collection ↗</a></p></section><section><details><summary>What was actually tested?</summary><ul>__CHECKS__</ul><p class="meta">Release ZIP SHA-256: __HASH__<br>Source commit: __SOURCE__</p></details></section><p class="footer">Research testnet. No monetary value or permanent unique-device identity. Your personal NFT key stays separate from the shared testnet key. Anyone holding this unlisted page link can view it. This page and its screenshots work offline; downloading the app or following evidence links needs internet access.</p></main></body></html>'''
for k,v in {'VERSION':e(m['version']),'DOWNLOAD':e(m['downloadURL']),'RELEASE':e(m['releaseURL']),'REQUIREMENTS':items(m['requirements']),'STEPS':items(m['steps']),'SCREENSHOTS':''.join(shots),'HELP':e(m.get('help','Save the diagnostic report and send it to the person coordinating your test.')),'LIMITS':items(m['limits']),'CHECKS':items(m['verifiedChecks']),'HASH':e(m['zipSHA256']),'SOURCE':e(m['sourceCommit'])}.items():page=page.replace('__'+k+'__',v)
